const displayFormulae={
 "σₕ(x,y,z)=(x,y,−z)<br>I=C₂σₕ=S₂":String.raw`\begin{gathered}\sigma_h(x,y,z)=(x,y,-z)\\I=C_2\sigma_h=S_2\end{gathered}`,
 "(u,v)=(x,y)/(1+|z|)":String.raw`(u,v)=\frac{(x,y)}{1+|z|}`,
 "g′=xgx⁻¹":String.raw`g'=xgx^{-1}`,
 "b C b⁻¹=C⁻¹ &nbsp; · &nbsp; σᵥ C σᵥ=C⁻¹<br>σₕ C σₕ=C":String.raw`\begin{gathered}bCb^{-1}=C^{-1},\qquad\sigma_vC\sigma_v=C^{-1}\\\sigma_hC\sigma_h=C\end{gathered}`,
 "rⁿ=E, &nbsp; b²=E, &nbsp; brb⁻¹=r⁻¹<br>Dₙ={rᵏ, rᵏb : 0≤k&lt;n}":String.raw`\begin{gathered}r^n=E,\quad b^2=E,\quad brb^{-1}=r^{-1}\\D_n=\{r^k,r^kb:0\le k<n\}\end{gathered}`,
 "h·x/a + k·y/b + l·z/c = 1":String.raw`h\frac{x}{a}+k\frac{y}{b}+l\frac{z}{c}=1`,
 "2cos(2π/n) ∈ {−2,−1,0,1,2}<br>n ∈ {1,2,3,4,6}":String.raw`\begin{gathered}2\cos(2\pi/n)\in\{-2,-1,0,1,2\}\\n\in\{1,2,3,4,6\}\end{gathered}`,
 "1/p + 1/q &gt; 1/2":String.raw`\frac1p+\frac1q>\frac12`,
 "G=H ∪ AH, &nbsp; |G|=2|H|, &nbsp; G/H≅C₂":String.raw`G=H\cup AH,\qquad |G|=2|H|,\qquad G/H\cong C_2`,
 "|Dₙh|=|Dₙd|=4n<br>I∈Dₙh ⇔ n par &nbsp; · &nbsp; I∈Dₙd ⇔ n impar":String.raw`\begin{gathered}|D_{nh}|=|D_{nd}|=4n\\I\in D_{nh}\Longleftrightarrow n\text{ par}\\I\in D_{nd}\Longleftrightarrow n\text{ impar}\end{gathered}`,
 "Oₕ=O×Cᵢ &nbsp; · &nbsp; Yₕ=Y×Cᵢ":String.raw`O_h=O\times C_i,\qquad Y_h=Y\times C_i`,
 "3̅ = C₃·I → grupo S₆<br>6̅ = C₆·I → grupo C₃h<br>1̅ = I &nbsp; · &nbsp; 2̅ = σ":String.raw`\begin{aligned}\overline3&=C_3\cdot I\;\to\;\text{grupo }S_6\\\overline6&=C_6\cdot I\;\to\;\text{grupo }C_{3h}\\\overline1&=I,\qquad\overline2=\sigma\end{aligned}`,
 "(RᵋA)(RᵝB)=Rᵋ⁺ᵝAB<br>Los exponentes de R se suman módulo 2.":String.raw`\begin{gathered}(R^\varepsilon A)(R^\beta B)=R^{\varepsilon+\beta}AB\\\text{Los exponentes de }R\text{ se suman módulo 2.}\end{gathered}`,
 "G′=H ∪ R(G∖H)":String.raw`G'=H\cup R(G\setminus H)`
};
